    DROP POLICY IF EXISTS "customers_full_access" ON public.customers;
    CREATE POLICY "customers_full_access" ON public.customers FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
    DROP POLICY IF EXISTS "suppliers_full_access" ON public.suppliers;
    CREATE POLICY "suppliers_full_access" ON public.suppliers FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
    DROP POLICY IF EXISTS "items_full_access" ON public.items;
    CREATE POLICY "items_full_access" ON public.items FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
    DROP POLICY IF EXISTS "invoices_full_access" ON public.invoices;
    CREATE POLICY "invoices_full_access" ON public.invoices FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
    DROP POLICY IF EXISTS "inv_items_full_access" ON public.invoice_items;
    CREATE POLICY "inv_items_full_access" ON public.invoice_items FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
    DROP POLICY IF EXISTS "journals_full_access" ON public.journal_entries;
    CREATE POLICY "journals_full_access" ON public.journal_entries FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
    DROP POLICY IF EXISTS "vouchers_full_access" ON public.payment_vouchers;
    CREATE POLICY "vouchers_full_access" ON public.payment_vouchers FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
EXCEPTION WHEN others THEN NULL;
END $$;

-- التأكد من وجود القيد الفريد لشجرة الحسابات (company_id, code) للتعامل الآمن مع التعارض
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'uq_coa_company_code'
    ) AND NOT EXISTS (
        SELECT 1 FROM pg_indexes WHERE indexname = 'uq_coa_company_code'
    ) THEN
        ALTER TABLE public.chart_of_accounts ADD CONSTRAINT uq_coa_company_code UNIQUE (company_id, code);
    END IF;
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

