-- ==============================================================================
-- 10. تأكيد ومراجعة اكتمال البيانات المستوردة
-- ==============================================================================
DO $$
DECLARE
    v_acc_cnt INT;
    v_cust_cnt INT;
    v_item_cnt INT;
    v_inv_cnt INT;
    v_vch_cnt INT;
    v_jrn_cnt INT;
BEGIN
    SELECT count(*) INTO v_acc_cnt FROM public.chart_of_accounts WHERE company_id = '20000000-0000-0000-0000-000000000001'::uuid;
    SELECT count(*) INTO v_cust_cnt FROM public.customers WHERE company_id = '20000000-0000-0000-0000-000000000001'::uuid;
    SELECT count(*) INTO v_item_cnt FROM public.items WHERE company_id = '20000000-0000-0000-0000-000000000001'::uuid;
    SELECT count(*) INTO v_inv_cnt FROM public.invoices WHERE company_id = '20000000-0000-0000-0000-000000000001'::uuid;
    SELECT count(*) INTO v_vch_cnt FROM public.payment_vouchers WHERE company_id = '20000000-0000-0000-0000-000000000001'::uuid;
    SELECT count(*) INTO v_jrn_cnt FROM public.journal_entries WHERE company_id = '20000000-0000-0000-0000-000000000001'::uuid;

    RAISE NOTICE '=== تم رفع واعتماد بيانات مطحنة الوليد بنجاح تام وبصيغة UUID القياسية وبدون أي تعارض ===';
    RAISE NOTICE 'الحسابات المالية: %', v_acc_cnt;
    RAISE NOTICE 'العملاء والجمعيات: %', v_cust_cnt;
    RAISE NOTICE 'أصناف المخزون: %', v_item_cnt;
    RAISE NOTICE 'الفواتير: %', v_inv_cnt;
    RAISE NOTICE 'سندات القبض/الصرف: %', v_vch_cnt;
    RAISE NOTICE 'قيود اليومية: %', v_jrn_cnt;
END $$;
